//! The adjacently-tagged shape (`{"kind": ..., "params": ...}`) must be what a TypeScript
//! consumer generated by `ts-codegen` would actually receive over the
//! wire — not just something that happens to derive without error.

use wincmd_clip_rules::{BuiltinPattern, MatchKind, StructuredKind};

/// Spot-check the actual JSON shape a console/TS consumer would see for
/// each of the four `MatchKind` variants — adjacently tagged as
/// `{"kind": "...", "params": ...}`, including the two variants
/// (`Structured`/`Builtin`) that wrap another plain-string enum, which
/// internally-tagged serde cannot represent at all (see `rule.rs`'s doc
/// comment on `MatchKind` for why adjacent tagging was chosen).
#[test]
fn adjacent_tagging_shape_is_kind_and_params() {
    let phrase = serde_json::to_value(MatchKind::Phrase {
        value: "x".into(),
        case_sensitive: true,
    })
    .unwrap();
    assert_eq!(phrase["kind"], "phrase");
    assert_eq!(phrase["params"]["value"], "x");
    assert_eq!(phrase["params"]["case_sensitive"], true);

    let structured =
        serde_json::to_value(MatchKind::Structured(StructuredKind::PaymentCard)).unwrap();
    assert_eq!(structured["kind"], "structured");
    assert_eq!(structured["params"], "payment_card");

    let builtin = serde_json::to_value(MatchKind::Builtin(BuiltinPattern::NpmToken)).unwrap();
    assert_eq!(builtin["kind"], "builtin");
    assert_eq!(builtin["params"], "npm_token");
}
